mapper.sql:
WHERE customer_contacts.is_active = 3
AND customer_contacts.contact_type = 2
AND (
    customer_contacts.customer_id IS NULL
    OR customer_contacts.customer_id IN (
        SELECT customer_id FROM customer_companies WHERE company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{userId})
    )
)

    AND (
        customer_contacts.contact_name LIKE CONCAT("%", #{filter.searchText}, "%")
        OR customer_contacts.contact_telephone LIKE CONCAT("%", #{filter.searchText}, "%")
        OR customer_contacts.contact_email LIKE CONCAT("%", #{filter.searchText}, "%")
    )


    AND customer_contacts.customer_id = #{filter.leadId}


    AND customer_contacts.created_by = #{userId}

mapper.select:
SELECT



GROUP BY customer_contacts.id
ORDER BY


        ${filter.orderBy}


        customer_contacts.id DESC



    LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT


WHERE customer_contacts.is_active = 3
AND customer_contacts.contact_type = 2
AND (
    customer_contacts.customer_id IS NULL
    OR customer_contacts.customer_id IN (
        SELECT customer_id FROM customer_companies WHERE company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{userId})
    )
)
AND customer_contacts.id = #{id}

SELECT COUNT(id)
FROM customer_contacts
WHERE is_active = 3
AND contact_type = 2
AND contact_name = #{contactName}

    AND id != #{id}
